import{_ as t,o,c as a,a5 as s}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"FR 3.8.3 — View Dashboard Post","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/07-publishing-social/3-8-3-view-dashboard-post/spec.md","filePath":"feature/srs/07-publishing-social/3-8-3-view-dashboard-post/spec.md"}'),r={name:"feature/srs/07-publishing-social/3-8-3-view-dashboard-post/spec.md"};function d(n,e,i,c,l,g){return o(),a("div",null,[...e[0]||(e[0]=[s('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-8-3-—-view-dashboard-post" tabindex="-1">FR 3.8.3 — View Dashboard Post <a class="header-anchor" href="#fr-3-8-3-—-view-dashboard-post" aria-label="Permalink to &quot;FR 3.8.3 — View Dashboard Post&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.8.3</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-109</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">View Dashboard Post</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Publishing &amp; Social (<code>3.8</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20, BR-55</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01, MSG02, MSG03, MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Provide a unified, timezone-accurate Workspace Social Publishing Dashboard &amp; Calendar (<code>GET /api/v1/workspaces/{workspaceId}/posts/dashboard</code>, <code>/posts</code>, <code>/schedule</code>) aggregating post KPIs, status breakdowns (<code>DRAFT</code>, <code>SCHEDULED</code>, <code>PUBLISHING</code>, <code>PUBLISHED</code>, <code>PARTIAL_FAILURE</code>, <code>FAILED</code>), and platform distribution across Facebook, Instagram, TikTok, and Threads.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized member holding <code>Owner, Manager, Creator, Client</code> in a Workspace, I want to execute <strong>View Dashboard Post</strong> reliably across BrandHub&#39;s supported social publishing pipeline (<strong>Facebook, Instagram, TikTok, Threads</strong>) so that approved brand content is delivered, previewed, scheduled, and audited safely with full tenant isolation (<code>BR-20, BR-55</code>).</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Workspace Scope (<code>BR-20</code>):</strong> Only authenticated Workspace members with role in <code>Owner, Manager, Creator, Client</code> may invoke the public REST endpoints for <code>View Dashboard Post</code>; unauthorized roles or cross-workspace requests fail deterministically with <code>403 FORBIDDEN</code> (<code>MSG07</code>).</li><li><strong>Four-Platform Scope Discipline:</strong> Strictly supports <strong>Facebook</strong>, <strong>Instagram</strong>, <strong>TikTok</strong>, and <strong>Threads</strong> — legacy/de-scoped platforms (such as Zalo OA or LinkedIn) are rejected at validation boundaries (<code>MSG02</code>).</li><li><strong>Production Pipeline &amp; Idempotency:</strong></li></ol><ul><li><strong>1. Multi-Dimensional MongoDB Aggregation:</strong> <code>PostService.getDashboard()</code> queries <code>posts</code> (<code>PostDocument</code>) scoped to <code>workspaceId</code> with compound index <code>{workspaceId, status, scheduledAt}</code>, computing total published, upcoming scheduled, failed/attention items, and per-platform counts (<code>FACEBOOK</code>, <code>INSTAGRAM</code>, <code>TIKTOK</code>, <code>THREADS</code>).</li><li><strong>2. Workspace Timezone Alignment:</strong> Date boundaries and monthly calendar buckets (<code>getSchedule</code>) evaluate in the Workspace&#39;s configured IANA timezone (default <code>Asia/Ho_Chi_Minh</code>), preventing midnight off-by-one shifts between Web and Mobile.</li><li><strong>3. Bounded Batch Lookup:</strong> <code>taskIds</code> filter enforces <code>ids.size() &lt;= 200</code> (<code>ErrorCode.INVALID_REQUEST</code> on overflow) so large Campaign views query efficiently.</li></ul><ol start="4"><li><strong>Token &amp; Credential Security:</strong> Raw OAuth access/refresh tokens are encrypted at rest via AES-256-GCM (<code>CryptoUtils</code>) and never returned in client-facing <code>ApiResponse&lt;T&gt;</code> DTOs or written to application logs.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All buttons, platform badges, status pills, validation alerts, and modal copy use synchronized key-parallel entries (<code>calendar.dashboard.*</code>, <code>calendar.filters.*</code>, <code>posts.status.*</code> in <code>src/i18n/locales/{vi,en}/calendar.json</code>) on <code>brandhub-web</code> and <code>tr()</code> on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces (<code>pages/calendar/index.tsx</code> (<code>ContentCalendar.tsx</code>, <code>CalendarFilterBar.tsx</code>, <code>PlatformFilter.tsx</code>, <code>StatusFilter.tsx</code>), <code>pages/workspace/components/SocialQuickSnapshot.tsx</code> on Web and <code>src/screens/more/PostDashboardScreen.tsx</code>, <code>src/screens/calendar/CalendarScreen.tsx</code>, <code>src/services/postDashboardService.ts</code> on Mobile) use semantic CSS variables / Tailwind <code>dark:</code> variants and <code>useAppPreferences().palette</code> tokens with WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/calendar/index.tsx</code> (<code>ContentCalendar.tsx</code>, <code>CalendarFilterBar.tsx</code>, <code>PlatformFilter.tsx</code>, <code>StatusFilter.tsx</code>), <code>pages/workspace/components/SocialQuickSnapshot.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/PostDashboardScreen.tsx</code>, <code>src/screens/calendar/CalendarScreen.tsx</code>, <code>src/services/postDashboardService.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / In-Flight:</strong> Skeleton placeholders on read views; spinner + disabled action button on mutations to prevent duplicate submissions.</li><li><strong>Empty:</strong> Contextual guidance card (e.g., prompt to connect social account via FR 3.8.1 or create/schedule a post via FR 3.8.6) with localized CTA.</li><li><strong>Success:</strong> Immediate <code>TanStack Query</code> cache invalidation, live status badge update, and localized toast notification.</li><li><strong>Error / Retryable Failure:</strong> Structured inline banner displaying localized error reason mapped from <code>MSG01, MSG02, MSG03, MSG07</code> without losing draft edits.</li></ul></li></ul><h2 id="_5-api-messaging-contract" tabindex="-1">5. API &amp; Messaging Contract <a class="header-anchor" href="#_5-api-messaging-contract" aria-label="Permalink to &quot;5. API &amp; Messaging Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Endpoint / Upstream Route</th><th style="text-align:left;">Auth / Security</th><th style="text-align:left;">Controller / Service Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/posts/dashboard?dateRange={r}&amp;platform={p}&amp;status={s}&amp;timezone={tz}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>PostController.getDashboard()</code> -&gt; aggregates KPIs &amp; recent activity in Workspace timezone (<code>Asia/Ho_Chi_Minh</code> default)</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/posts?status={s}&amp;taskIds={ids}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>PostController.list()</code> -&gt; filtered post list (<code>MAX_TASK_IDS = 200</code> guard)</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/posts/schedule?month={YYYY-MM}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>PostController.getSchedule()</code> -&gt; monthly calendar slot grid</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>INVALID_REQUEST</code> (<code>400</code>, <code>MSG02</code>): <code>taskIds</code> exceeds <code>200</code>, invalid <code>YYYY-MM</code> month format, or unrecognized IANA timezone.</li><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): Caller is not a member of <code>{workspaceId}</code>.</li><li><strong>Duplicate Delivery / Network Retry:</strong> <code>PublishJobConsumer</code> enforces Redis lock <code>processingPostIds:{postId}:{platform}</code> (<code>30m</code> TTL) and <code>DefaultClassMapper</code> cross-service <code>PublishJobMessage</code> compatibility so broker redeliveries never double-post to a Client&#39;s live social feed.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Domain Index &amp; Sibling FRs:</strong> <a href="./../README.html">3.8 Publishing &amp; Social Index</a> · <a href="./../3-8-1-connect-social-account/spec.html">FR 3.8.1 — Connect Social Account</a> · <a href="./../3-8-7-track-post-status/spec.html">FR 3.8.7 — Track Post Status</a></li><li><strong>Consolidated Extension Module:</strong> <a href="./../../../modules/07-billing-publisher-and-observability/social-publisher-resilience/spec.html"><code>social-publisher-resilience</code></a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/07-publishing-social.html">BA 3.8 Publishing &amp; Social</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified across <code>brandhub-business-service</code> and <code>brandhub-publisher-service</code> JUnit suites, RabbitMQ + Redis lock integration checks, Web &amp; Mobile UI integration, <code>vi.json</code>/<code>en.json</code> parity, and Light/Dark mode verification (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> De-scoped platforms (Zalo OA), livestream broadcasting, or automated paid ad-spend boosting.</li></ul>',21)])])}const h=t(r,[["render",d]]);export{u as __pageData,h as default};
